using System.Drawing;using System.Windows.Forms;
namespace LSE.AutoCADElectrical.ProjectDoctor;
public sealed class DoctorSettingsForm:Form{readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();
 public DoctorSettingsForm(){Text="LSE_Doctor Settings";StartPosition=FormStartPosition.CenterParent;Size=new Size(1000,640);MinimumSize=new Size(760,520);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,230));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;
  Add(p,"Template project (.wdp) = the standard",nameof(s.TemplateProjectPath),s.TemplateProjectPath,r++,"AutoCAD Electrical project (*.wdp)|*.wdp");Add(p,"Doctor rules JSON",nameof(s.RulesConfigPath),s.RulesConfigPath,r++,"JSON (*.json)|*.json");Add(p,"Projects root (scan default)",nameof(s.ProjectsRootFolder),s.ProjectsRootFolder,r++,"folder");
  Add(p,"Backup folder name (inside the project)",nameof(s.BackupFolderName),s.BackupFolderName,r++);Add(p,"Backups to keep per project",nameof(s.BackupsToKeep),s.BackupsToKeep.ToString(),r++);Add(p,"Active project LISP (sets USERS1)",nameof(s.ActiveProjectLisp),s.ActiveProjectLisp,r++);Add(p,"Reload project LISP ({WDP})",nameof(s.ActivateProjectLisp),s.ActivateProjectLisp,r++);
  Check(p,"Check drawing contents by default (LSEDOCTOR)",nameof(s.CheckDrawings),s.CheckDrawings,r++);Check(p,"Recommend inserting a missing WD_M block from the template drawing",nameof(s.InsertMissingWdm),s.InsertMissingWdm,r++);Check(p,"Folder scan checks drawing contents too (slow)",nameof(s.ScanChecksDrawings),s.ScanChecksDrawings,r++);Check(p,"Reload the active project after it is repaired",nameof(s.ReactivateAfterRepair),s.ReactivateAfterRepair,r++);Check(p,"Show the repair report after each repair",nameof(s.ShowReportAfterRepair),s.ShowReportAfterRepair,r++);
  var save=new Button{Text="Save",Dock=DockStyle.Fill};save.Click+=(_,_)=>{try{s.TemplateProjectPath=boxes[nameof(s.TemplateProjectPath)].Text.Trim();s.RulesConfigPath=boxes[nameof(s.RulesConfigPath)].Text.Trim();s.ProjectsRootFolder=boxes[nameof(s.ProjectsRootFolder)].Text.Trim();s.BackupFolderName=boxes[nameof(s.BackupFolderName)].Text.Trim();s.ActiveProjectLisp=boxes[nameof(s.ActiveProjectLisp)].Text.Trim();s.ActivateProjectLisp=boxes[nameof(s.ActivateProjectLisp)].Text.Trim();
   if(!int.TryParse(boxes[nameof(s.BackupsToKeep)].Text.Trim(),out int keep)||keep<1)throw new InvalidOperationException("Backups to keep must be a whole number of 1 or more.");s.BackupsToKeep=keep;if(s.BackupFolderName.Length==0||s.BackupFolderName.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new InvalidOperationException("Backup folder name must be a valid folder name.");
   s.CheckDrawings=checks[nameof(s.CheckDrawings)].Checked;s.InsertMissingWdm=checks[nameof(s.InsertMissingWdm)].Checked;s.ScanChecksDrawings=checks[nameof(s.ScanChecksDrawings)].Checked;s.ReactivateAfterRepair=checks[nameof(s.ReactivateAfterRepair)].Checked;s.ShowReportAfterRepair=checks[nameof(s.ShowReportAfterRepair)].Checked;SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"LSE_Doctor Settings");}};
  var diag=new Button{Text="Diagnostics",Dock=DockStyle.Fill};diag.Click+=(_,_)=>{using var f=new TextReportForm("LSE_Doctor Diagnostics",DiagnosticsService.BuildReport());f.ShowDialog(this);};p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(diag,0,r);p.Controls.Add(save,2,r);Controls.Add(p);}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string? browse=null){p.RowStyles.Add(new(SizeType.Absolute,48));p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse is null)return;var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(browse=="folder"){using var f=new FolderBrowserDialog{SelectedPath=Directory.Exists(t.Text)?t.Text:""};if(f.ShowDialog()==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=browse,FileName=t.Text};if(f.ShowDialog()==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);}
 void Check(TableLayoutPanel p,string label,string key,bool value,int row){p.RowStyles.Add(new(SizeType.Absolute,34));var c=new CheckBox{Text=label,Checked=value,AutoSize=true,Anchor=AnchorStyles.Left};checks[key]=c;p.Controls.Add(c,1,row);p.SetColumnSpan(c,2);}
}
